function longestNiceSubstring(s) {
  if (s.length < 2) {
    return "";
  }
  const present = new Set(s);
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (present.has(ch.toLowerCase()) && present.has(ch.toUpperCase())) {
      continue;
    }
    const before = longestNiceSubstring(s.slice(0, i));
    const after = longestNiceSubstring(s.slice(i + 1));
    return after.length > before.length ? after : before;
  }
  return s;
}

