function longestNiceSubstring(s) {
  let answer = '';
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j <= s.length; j++) {
      const part = s.slice(i, j);
      let nice = true;
      for (const c of part) {
        const other = c === c.toLowerCase() ? c.toUpperCase() : c.toLowerCase();
        if (!part.includes(other)) nice = false;
      }
      if (nice && part.length > answer.length) answer = part;
    }
  }
  return answer;
}

