function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = [];
  const kinds = large ? int(3, 10) : int(1, 4);
  for (let i = 0; i < kinds; i++) {
    const letter = letters[int(0, 25)];
    const roll = rand();
    if (roll < 0.6) alphabet.push(letter, letter.toUpperCase());
    else if (roll < 0.8) alphabet.push(letter);
    else alphabet.push(letter.toUpperCase());
  }
  const n = large ? int(80, 100) : int(1, 10);
  let s = '';
  for (let i = 0; i < n; i++) s += alphabet[int(0, alphabet.length - 1)];
  return [s];
}
